CREATE OR REPLACE PROCEDURE award_hat_trick(driver_id INTEGER, race_id INTEGER)
LANGUAGE plpgsql
AS $$
DECLARE
    has_pole BOOLEAN;
    has_winner BOOLEAN;
    has_fastest_lap BOOLEAN;
    has_points_finish BOOLEAN;
BEGIN
    -- Check Pole Position
    SELECT EXISTS (
        SELECT 1 FROM qualifying 
        WHERE pilotrec = driver_id AND rbind = race_id AND px_pos = 1
    ) INTO has_pole;

    -- Check Race Winner
    SELECT EXISTS (
        SELECT 1 FROM driver_standings 
        WHERE drive_link = driver_id AND rlink = race_id AND px = 1
    ) INTO has_winner;

    -- Check Fastest Lap Award (fastest lap + points finish)
    SELECT EXISTS (
        SELECT 1 FROM lap_times lt
        INNER JOIN (SELECT rc_index, MIN(msec_val) as min_ms FROM lap_times GROUP BY rc_index) fl
            ON lt.rc_index = fl.rc_index AND lt.msec_val = fl.min_ms
        WHERE lt.rc_index = race_id AND lt.wheel_unit = driver_id
    ) INTO has_fastest_lap;

    -- Check Points Finish (top 10)
    SELECT EXISTS (
        SELECT 1 FROM driver_standings 
        WHERE drive_link = driver_id AND rlink = race_id AND px IS NOT NULL AND px <= 10
    ) INTO has_points_finish;

    -- If all conditions met, insert record
    IF has_pole AND has_winner AND has_fastest_lap AND has_points_finish THEN
        INSERT INTO hat_tricks (driver_id, race_id) VALUES (driver_id, race_id);
    END IF;
END;
$$;

